/**
 * Default i18n bond setup.
 *
 * Composes @molecule/app-i18n-default-react with this app's English UI
 * translations, a per-locale lazy loader, and the companion locale
 * bonds for every shared @molecule/app-* dependency. The dynamic-import
 * template literal MUST stay in the app so Vite can code-split each
 * locale's `ui.ts` into its own chunk.
 *
 * The `packageLocales` array is generated by
 * `scripts/wire-app-locale-bonds.mjs` from this app's package.json
 * dependencies. Re-run that script after adding/removing any
 * `@molecule/app-*` dep to refresh this list.
 */

import { setupI18nDefault as setupI18nProvider } from '@molecule/app-i18n-default-react'
import * as aiChatLocales from '@molecule/app-locales-ai-chat'
import * as authLocales from '@molecule/app-locales-auth'
import * as billingLocales from '@molecule/app-locales-billing'
import * as codeEditorLocales from '@molecule/app-locales-code-editor'
import * as footerLocales from '@molecule/app-locales-footer'
import * as formsLocales from '@molecule/app-locales-forms'
import * as httpLocales from '@molecule/app-locales-http'
import * as i18nLocales from '@molecule/app-locales-i18n'
import * as iconsLocales from '@molecule/app-locales-icons'
import * as ideLocales from '@molecule/app-locales-ide'
import * as livePreviewLocales from '@molecule/app-locales-live-preview'
import * as oauthButtonsLocales from '@molecule/app-locales-oauth-buttons'
import * as planUpdatedPageLocales from '@molecule/app-locales-plan-updated-page'
import * as pushLocales from '@molecule/app-locales-push'
import * as reactLocales from '@molecule/app-locales-react'
import * as rootErrorBoundaryLocales from '@molecule/app-locales-root-error-boundary'
import * as routingLocales from '@molecule/app-locales-routing'
import * as storageLocales from '@molecule/app-locales-storage'
import * as uiLocales from '@molecule/app-locales-ui'
import * as utilitiesLocales from '@molecule/app-locales-utilities'
import * as versionLocales from '@molecule/app-locales-version'

import { ui as en } from '../locales/en/ui.js'

const lazyLoadUi = (code: string): Promise<Record<string, string>> =>
  import(`../locales/${code}/ui.ts`).then((m: { ui: Record<string, string> }) => m.ui)

/**
 * Languages this app actually ships `src/locales/<code>/ui.ts` translations
 * for — every directory under `src/locales/` except `en` (the eager
 * bootstrap, always kept). Passing this list to the provider short-circuits
 * its boot-time support probe, which otherwise dynamic-imports every non-en
 * locale module on EVERY page load just to prune empty ones. In dev mode
 * that is ~79 HTTP module requests per navigation for an answer that never
 * changes — a large share of the request storm that exhausted the browser's
 * request budget on this app (net::ERR_INSUFFICIENT_RESOURCES,
 * 2026-09-26 flagship audit). The outcome is identical: this app translates
 * all 78 of these languages, and locales outside the list are pruned
 * synchronously instead of probed.
 *
 * Keep in sync with `src/locales/` when adding or removing languages.
 */
const supportedLocales = [
  'af',
  'am',
  'ar',
  'az',
  'be',
  'bg',
  'bn',
  'bs',
  'ca',
  'cs',
  'cy',
  'da',
  'de',
  'el',
  'es',
  'et',
  'eu',
  'fa',
  'fi',
  'fil',
  'fr',
  'ga',
  'gl',
  'gu',
  'ha',
  'he',
  'hi',
  'hr',
  'hu',
  'hy',
  'id',
  'ig',
  'is',
  'it',
  'ja',
  'ka',
  'kk',
  'km',
  'kn',
  'ko',
  'ky',
  'lo',
  'lt',
  'lv',
  'mk',
  'ml',
  'mn',
  'mr',
  'ms',
  'mt',
  'my',
  'nb',
  'ne',
  'nl',
  'pa',
  'pl',
  'pt',
  'ro',
  'ru',
  'si',
  'sk',
  'sl',
  'sq',
  'sr',
  'sv',
  'sw',
  'ta',
  'te',
  'th',
  'tr',
  'uk',
  'ur',
  'uz',
  'vi',
  'yo',
  'zh',
  'zh-TW',
  'zu',
] as const

export const i18nProvider = setupI18nProvider({
  enUi: en,
  lazyLoadUi,
  supportedLocales: [...supportedLocales],
  packageLocales: [
    aiChatLocales,
    authLocales,
    billingLocales,
    codeEditorLocales,
    footerLocales,
    formsLocales,
    httpLocales,
    i18nLocales,
    iconsLocales,
    ideLocales,
    livePreviewLocales,
    oauthButtonsLocales,
    planUpdatedPageLocales,
    pushLocales,
    reactLocales,
    rootErrorBoundaryLocales,
    routingLocales,
    storageLocales,
    uiLocales,
    utilitiesLocales,
    versionLocales,
  ],
})

/**
 * Called from bonds/index.ts during setupProviders(). The i18n
 * provider was already wired at module-eval time above — this
 * function exists for compat with the legacy bond-setup contract
 * and is a no-op.
 */
export function setupI18nDefault(): void {
  // intentionally empty
}
